insert into earned.quest_templates (id, version, category, title, content) values ('fit-enter-gym', 1, 'fitness', 'Walk into the gym', '{"id":"fit-enter-gym","category":"fitness","title":"Walk into the gym","purpose":"Most workouts are lost at the door. Arriving is the habit.","minimumAction":"Arrive inside your gym''s area and check in.","extension":"Complete your planned workout.","cue":"After you park or get off the bus at the gym.","schedule":{"kind":"weekdays","days":[1,3,5],"window":{"start":"05:30","end":"09:00"}},"verification":{"mode":"gps","criteria":["Phone location inside the saved gym area"],"locationHint":"Your gym''s entrance"},"maxXp":20,"reviewIntervalDays":30}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.quest_templates (id, version, category, title, content) values ('fit-shoes-out', 1, 'fitness', 'Set out running shoes', '{"id":"fit-shoes-out","category":"fitness","title":"Set out running shoes","purpose":"Remove tomorrow morning''s first decision.","minimumAction":"Place your running shoes by the door, laces loosened.","extension":"Go for a run or brisk walk of any length.","cue":"Right after dinner dishes are done.","schedule":{"kind":"daily","window":{"start":"17:00","end":"23:00"}},"verification":{"mode":"photo","criteria":["A pair of athletic shoes","Shoes placed on a floor near a door or entryway"]},"maxXp":20,"reviewIntervalDays":30}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
