insert into earned.quest_templates (id, version, category, title, content) values ('fit-sleep-setup', 1, 'fitness', 'Set the room for sleep', '{"id":"fit-sleep-setup","category":"fitness","title":"Set the room for sleep","purpose":"Recovery is training. A dark, ready room makes bedtime the easy choice.","minimumAction":"Close the blinds or curtains and turn on only a dim lamp.","extension":"Lights out by your planned bedtime, phone charging outside the bedroom.","cue":"At your planned wind-down time.","schedule":{"kind":"daily","window":{"start":"20:00","end":"24:00"}},"verification":{"mode":"photo","criteria":["Closed blinds or curtains","A dim lamp or low light","No people visible"]},"maxXp":20,"reviewIntervalDays":21}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
