insert into earned.quest_templates (id, version, category, title, content) values ('biz-workspace', 1, 'business', 'Prepare the workspace', '{"id":"biz-workspace","category":"business","title":"Prepare the workspace","purpose":"A cleared desk is a decision to work.","minimumAction":"Clear your desk and set out only what today''s top task needs.","extension":"Work 90 focused minutes on the top task.","cue":"Before you open email.","schedule":{"kind":"weekdays","days":[1,2,3,4,5],"window":{"start":"06:00","end":"11:00"}},"verification":{"mode":"photo","criteria":["A desk or table surface that is mostly clear","A laptop, notebook, or tools set out for work"]},"maxXp":20,"reviewIntervalDays":30}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
