insert into earned.battle_definitions (id, version, category, title, content) values ('harbor-lease', 1, 'negotiation', 'The Harbor Lease', '{"id":"harbor-lease","version":1,"title":"The Harbor Lease","category":"negotiation","opponent":{"name":"Marla Quinn","role":"Landlord, Quinn Wharf Holdings (fictional)","style":"Patient, anchors high","color":"#2A9D8F"},"objective":"Lease the waterfront warehouse on terms your café can survive.","meterLabel":"Deal value","startMeter":10,"target":32,"capital":6,"conditions":["Two other tenants are touring the space.","Quinn values long-term tenants over the highest rent."],"weakness":"Quinn''s warehouse has sat empty for eight months; every month costs her.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"Opening terms","situation":"Quinn slides over a lease at the top of the market and waits.","signal":"She keeps glancing at a stack of other applications.","intents":[{"id":"anchor-high","label":"Anchors high","pressure":8,"weakTo":["research"],"detail":"Opens 30% above comparable rents to see if you flinch.","weight":10},{"id":"rival-tenant","label":"Plays the rival tenant","pressure":9,"weakTo":["negotiate"],"detail":"Mentions a national chain is ''very interested''.","weight":10}],"choices":[{"id":"comps","label":"Pull comparable leases","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Study nearby rents and vacancy history. Reveals her next move.","reveals":true},{"id":"counter-offer","label":"Make a firm counter","tag":"negotiate","stat":"influence","cost":1,"power":7,"detail":"A clear number with reasons attached."},{"id":"walk-tour","label":"Tour the space with a contractor","tag":"execute","stat":"execution","cost":2,"power":8,"detail":"Price the build-out on the spot."},{"id":"hold-open","label":"Listen and take notes","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"Spend nothing; absorb the anchor.","defense":5}]},{"title":"Concessions","situation":"Quinn offers a small discount if you sign a ten-year term today.","signal":"Her assistant mentions the loading dock ''needs a little work''.","intents":[{"id":"long-term","label":"Pushes a long lock-in","pressure":10,"weakTo":["negotiate","research"],"detail":"Ten years, personal guarantee, no exit.","weight":10},{"id":"repairs-on-you","label":"Shifts repairs to you","pressure":9,"weakTo":["execute"],"detail":"Dock and roof repairs become your problem.","weight":10,"adapts":[{"tag":"execute","delta":-3}]}],"choices":[{"id":"tenant-improvements","label":"Ask for tenant-improvement credit","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Trade term length for build-out money.","exploits":true},{"id":"inspection","label":"Commission an inspection","tag":"execute","stat":"execution","cost":2,"power":9,"detail":"Put the repairs in writing before you sign."},{"id":"partner-landlord","label":"Offer a co-marketing partnership","tag":"invest","stat":"insight","cost":2,"power":7,"detail":"Feature the wharf in your branding; she gets foot traffic.","yield":1},{"id":"hold-concessions","label":"Ask for a week to decide","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"Keep Capital; let the pressure pass.","defense":5}]},{"title":"Signing day","situation":"Quinn is ready to sign, but the final draft has new clauses.","signal":"The draft arrived at 11 p.m. with tracked changes turned off.","intents":[{"id":"fine-print","label":"Hides clauses in the fine print","pressure":12,"weakTo":["research"],"detail":"A rent escalator buried on page 14.","weight":10},{"id":"deadline","label":"Imposes a deadline","pressure":11,"weakTo":["defend","negotiate"],"detail":"''Sign by noon or it goes to the chain.''","weight":10}],"choices":[{"id":"redline","label":"Redline every page","tag":"research","stat":"insight","cost":1,"power":6,"detail":"Read it all, line by line.","reveals":true},{"id":"vacancy-leverage","label":"Name the empty months","tag":"negotiate","stat":"influence","cost":1,"power":9,"detail":"Remind her what eight vacant months have cost.","requiresWeakness":true,"exploits":true},{"id":"sign-fast","label":"Sign and start building","tag":"execute","stat":"execution","cost":1,"power":10,"detail":"Lock it in and move."},{"id":"hold-signing","label":"Calmly restate your terms","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend; defend your position.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('supplier-squeeze', 1, 'negotiation', 'The Supplier Squeeze', '{"id":"supplier-squeeze","version":1,"title":"The Supplier Squeeze","category":"negotiation","opponent":{"name":"Dario Venn","role":"Sales director, Venn Grain Co. (fictional)","style":"Friendly, then firm","color":"#E76F51"},"objective":"Renew your flour contract without a 20% price hike.","meterLabel":"Margin protected","startMeter":8,"target":30,"capital":6,"conditions":["Wheat prices rose this quarter.","You are Venn''s third-largest bakery account."],"weakness":"Venn''s new mill is underused; they need volume more than price.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"The new price sheet","situation":"Dario emails a price sheet 20% higher, ''effective next month''.","signal":"The email is cheerful and mentions their new mill twice.","intents":[{"id":"market-excuse","label":"Blames the market","pressure":8,"weakTo":["research"],"detail":"Cites commodity prices that rose only 6%.","weight":10},{"id":"bundle-push","label":"Pushes a bigger bundle","pressure":7,"weakTo":["negotiate"],"detail":"Offers the old price if you buy specialty flours too.","weight":10}],"choices":[{"id":"commodity-data","label":"Check commodity data","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Compare their hike to actual wheat prices.","reveals":true},{"id":"call-dario","label":"Call Dario directly","tag":"negotiate","stat":"influence","cost":1,"power":7,"detail":"A relationship call before the paperwork."},{"id":"test-alt","label":"Test an alternative supplier","tag":"invest","stat":"insight","cost":2,"power":8,"detail":"Order a sample batch elsewhere."},{"id":"hold-sheet","label":"Acknowledge and wait","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Leverage","situation":"Dario offers ''a small courtesy discount'' of 5%.","signal":"He asks how many loaves you bake on weekends.","intents":[{"id":"volume-probe","label":"Probes your volume","pressure":9,"weakTo":["research","defend"],"detail":"Fishing for how dependent you are.","weight":10},{"id":"exclusive-ask","label":"Asks for exclusivity","pressure":10,"weakTo":["negotiate"],"detail":"Discount only if you drop every other supplier.","weight":10}],"choices":[{"id":"volume-commit","label":"Offer a volume commitment","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Guarantee more tonnage for a lower rate.","exploits":true},{"id":"forecast","label":"Share a 6-month forecast","tag":"execute","stat":"execution","cost":1,"power":8,"detail":"Show them a reliable, plannable account."},{"id":"co-op","label":"Form a buying co-op","tag":"invest","stat":"insight","cost":3,"power":10,"detail":"Join two other bakeries to buy together.","yield":1},{"id":"hold-leverage","label":"Keep numbers private","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"Reveal nothing.","defense":5}]},{"title":"Final offer","situation":"Dario says this is his best and final.","signal":"His manager is copied on the email for the first time.","intents":[{"id":"escalate","label":"Escalates to his manager","pressure":11,"weakTo":["negotiate"],"detail":"The manager wants a quick, clean win.","weight":10},{"id":"walk-away","label":"Threatens to drop the account","pressure":12,"weakTo":["invest","defend"],"detail":"Bluff: they need your volume.","weight":10}],"choices":[{"id":"mill-capacity","label":"Offer to fill their new mill","tag":"negotiate","stat":"influence","cost":1,"power":9,"detail":"Off-peak orders that fill unused capacity.","requiresWeakness":true,"exploits":true},{"id":"switch-ready","label":"Show the backup supplier","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Make it clear you can walk."},{"id":"accept-mid","label":"Accept a midpoint","tag":"execute","stat":"execution","cost":0,"power":6,"detail":"Take 10% and move on."},{"id":"hold-final","label":"Hold the line","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('studio-partnership', 1, 'negotiation', 'The Studio Partnership', '{"id":"studio-partnership","version":1,"title":"The Studio Partnership","category":"negotiation","opponent":{"name":"Priya Lanne","role":"Founder, Lanne Design Studio (fictional)","style":"Visionary, protective of equity","color":"#9B5DE5"},"objective":"Form a partnership with a design studio without giving away control.","meterLabel":"Partnership value","startMeter":10,"target":34,"capital":6,"conditions":["Priya has two other partnership offers.","Your product needs her brand by spring."],"weakness":"Priya''s studio needs steady revenue; she''s tired of feast-or-famine projects.","exploitBonus":4,"counterBonus":4,"rounds":[{"title":"First meeting","situation":"Priya likes your product but asks what''s in it for her team.","signal":"She talks about her designers'' burnout.","intents":[{"id":"equity-ask","label":"Asks for equity","pressure":9,"weakTo":["negotiate"],"detail":"Wants 15% of your company for brand work.","weight":10},{"id":"vision-test","label":"Tests your vision","pressure":8,"weakTo":["research","execute"],"detail":"Pokes holes in your roadmap.","weight":10}],"choices":[{"id":"studio-research","label":"Research her studio''s clients","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Who has she worked with, and how often?","reveals":true},{"id":"vision-deck","label":"Present the roadmap","tag":"execute","stat":"execution","cost":1,"power":8,"detail":"A tight, honest plan."},{"id":"rev-share","label":"Propose revenue share","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Share upside without giving up equity."},{"id":"hold-first","label":"Ask questions, offer nothing yet","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Terms","situation":"Priya proposes a joint brand with her name first.","signal":"She mentions an investor who ''loves co-branding''.","intents":[{"id":"name-first","label":"Insists on top billing","pressure":10,"weakTo":["negotiate"],"detail":"Her name leads every product page.","weight":10},{"id":"investor-pressure","label":"Brings in her investor","pressure":11,"weakTo":["research","invest"],"detail":"The investor wants board observer rights.","weight":10}],"choices":[{"id":"retainer","label":"Offer a monthly retainer","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Steady revenue for her team.","exploits":true},{"id":"pilot","label":"Run a 60-day pilot","tag":"execute","stat":"execution","cost":1,"power":8,"detail":"Prove the partnership before formalizing it."},{"id":"co-brand-terms","label":"Negotiate shared billing","tag":"negotiate","stat":"influence","cost":1,"power":9,"detail":"Alternating credit by product line."},{"id":"hold-terms","label":"Table it for next week","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Handshake","situation":"Priya is ready, but her lawyer adds an exclusivity clause.","signal":"The lawyer''s draft is 40 pages for a 6-page deal.","intents":[{"id":"exclusivity","label":"Demands exclusivity","pressure":12,"weakTo":["negotiate","defend"],"detail":"You could never work with another studio.","weight":10},{"id":"ip-grab","label":"Claims shared IP","pressure":11,"weakTo":["research"],"detail":"Joint ownership of designs she touches.","weight":10}],"choices":[{"id":"steady-pipeline","label":"Promise a steady project pipeline","tag":"negotiate","stat":"influence","cost":1,"power":10,"detail":"Guaranteed quarterly work, no exclusivity.","requiresWeakness":true,"exploits":true},{"id":"ip-audit","label":"Audit the IP clauses","tag":"research","stat":"insight","cost":1,"power":6,"detail":"Read what she''s actually claiming.","reveals":true},{"id":"ship-together","label":"Ship the first product together","tag":"execute","stat":"execution","cost":2,"power":10,"detail":"Momentum beats paperwork."},{"id":"hold-handshake","label":"Decline the clause politely","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('valley-expansion', 1, 'market_entry', 'Into the Valley', '{"id":"valley-expansion","version":1,"title":"Into the Valley","category":"market_entry","opponent":{"name":"Corbin Hale","role":"Owner, Hale Hardware (fictional)","style":"Entrenched, loyal customers","color":"#F4A261"},"objective":"Open your tool-rental shop in a town Hale has served for 30 years.","meterLabel":"Market share","startMeter":6,"target":30,"capital":7,"conditions":["Hale has deep community ties.","Contractors complain about Hale''s rental wait times."],"weakness":"Hale''s rental fleet is old and booked weeks out.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"Scouting the town","situation":"You have one storefront option and a modest budget.","signal":"Locals mention Hale sponsors every Little League team.","intents":[{"id":"loyalty","label":"Leans on loyalty","pressure":8,"weakTo":["research","negotiate"],"detail":"Reminds town he''s ''been here for you''.","weight":10},{"id":"price-match","label":"Announces price matching","pressure":9,"weakTo":["invest"],"detail":"Matches any competitor price.","weight":10}],"choices":[{"id":"contractor-survey","label":"Survey local contractors","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Ask what they actually need.","reveals":true},{"id":"grand-opening","label":"Plan a big grand opening","tag":"execute","stat":"execution","cost":3,"power":11,"detail":"Make a splash."},{"id":"sponsor-team","label":"Sponsor a team too","tag":"negotiate","stat":"influence","cost":2,"power":8,"detail":"Join the community, don''t fight it."},{"id":"hold-scout","label":"Open quietly","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"First customers","situation":"Your doors are open. Traffic is slow.","signal":"Hale''s lot is full of contractor trucks waiting.","intents":[{"id":"rumors","label":"Spreads ''out-of-towner'' talk","pressure":10,"weakTo":["negotiate"],"detail":"Coffee-shop gossip about big-city outsiders.","weight":10},{"id":"discount-blitz","label":"Launches a discount blitz","pressure":10,"weakTo":["defend","execute"],"detail":"20% off rentals for a month.","weight":10}],"choices":[{"id":"same-day","label":"Guarantee same-day rentals","tag":"execute","stat":"execution","cost":2,"power":9,"detail":"Serve the contractors Hale can''t.","exploits":true},{"id":"meet-greet","label":"Host a contractor breakfast","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Coffee, donuts, and a handshake."},{"id":"new-fleet","label":"Invest in newer equipment","tag":"invest","stat":"insight","cost":3,"power":11,"detail":"Better tools than the incumbent."},{"id":"hold-first","label":"Hold prices steady","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Hale responds","situation":"Hale buys a full-page ad in the county paper.","signal":"His nephew was seen pricing new equipment.","intents":[{"id":"fleet-upgrade","label":"Upgrades his fleet","pressure":12,"weakTo":["execute","research"],"detail":"Closes the gap you exploited.","weight":10},{"id":"exclusive-deals","label":"Signs exclusive contractor deals","pressure":11,"weakTo":["negotiate"],"detail":"Discounts for contractors who rent only from him.","weight":10}],"choices":[{"id":"booking-app","label":"Launch online booking","tag":"invest","stat":"insight","cost":2,"power":10,"detail":"Reserve tools at midnight from a truck."},{"id":"loyalty-program","label":"Start a contractor loyalty card","tag":"negotiate","stat":"influence","cost":1,"power":9,"detail":"Every 10th rental free."},{"id":"fleet-depth","label":"Stock the tools Hale is always out of","tag":"execute","stat":"execution","cost":2,"power":10,"detail":"Depth where it matters.","requiresWeakness":true,"exploits":true},{"id":"hold-hale","label":"Let the ad run its course","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('night-market', 1, 'market_entry', 'The Night Market Stall', '{"id":"night-market","version":1,"title":"The Night Market Stall","category":"market_entry","opponent":{"name":"The Ferro Twins","role":"Rival food truck, Ferro Bros. (fictional)","style":"Loud, fast, viral","color":"#E63946"},"objective":"Win a regular stall at the city night market.","meterLabel":"Crowd share","startMeter":8,"target":30,"capital":6,"conditions":["The market committee picks one new vendor this season.","Ferro''s videos get thousands of views."],"weakness":"The Ferros'' lines are long and their food runs out by 9 p.m.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"Trial night","situation":"You and the Ferros each get one trial night.","signal":"The twins are filming a teaser outside your setup.","intents":[{"id":"viral-video","label":"Posts a viral video","pressure":9,"weakTo":["execute"],"detail":"Their video draws a crowd away from you.","weight":10},{"id":"undercut","label":"Undercuts your price","pressure":8,"weakTo":["research"],"detail":"Half-price tacos for the first hour.","weight":10}],"choices":[{"id":"observe-lines","label":"Watch their lines and stock","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Time their service and count their trays.","reveals":true},{"id":"fast-service","label":"Optimize your service line","tag":"execute","stat":"execution","cost":1,"power":8,"detail":"Two-minute orders, every time."},{"id":"signature-dish","label":"Debut a signature dish","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Something no one else sells."},{"id":"hold-trial","label":"Keep the menu simple","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Word of mouth","situation":"The committee is watching crowd reactions.","signal":"A food blogger is in line at the Ferros'' truck.","intents":[{"id":"blogger","label":"Courts the blogger","pressure":10,"weakTo":["negotiate"],"detail":"Free food and a front-row interview.","weight":10},{"id":"crowd-surge","label":"Pulls a crowd surge","pressure":9,"weakTo":["defend","invest"],"detail":"Live music at their truck.","weight":10}],"choices":[{"id":"late-night","label":"Stay stocked until close","tag":"execute","stat":"execution","cost":2,"power":9,"detail":"Be the only food left at 10 p.m.","exploits":true},{"id":"blogger-chat","label":"Invite the blogger to taste","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Honest food, honest conversation."},{"id":"collab","label":"Propose a pairing with a drinks stall","tag":"invest","stat":"insight","cost":1,"power":7,"detail":"Bundle with the lemonade stand.","yield":1},{"id":"hold-word","label":"Focus on regulars","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Committee vote","situation":"The committee meets tomorrow.","signal":"The Ferros have printed petition cards.","intents":[{"id":"petition","label":"Runs a petition","pressure":11,"weakTo":["execute"],"detail":"Customers sign cards supporting the Ferros.","weight":10},{"id":"sabotage-rumor","label":"Questions your permits","pressure":12,"weakTo":["research","defend"],"detail":"Implies your health permit is lapsing.","weight":10}],"choices":[{"id":"permits","label":"Bring every permit, organized","tag":"research","stat":"insight","cost":1,"power":6,"detail":"Proof beats rumor.","reveals":true},{"id":"committee-pitch","label":"Pitch the committee directly","tag":"negotiate","stat":"influence","cost":1,"power":9,"detail":"Explain what you add to the market."},{"id":"closing-crowd","label":"Serve the after-nine crowd","tag":"execute","stat":"execution","cost":1,"power":9,"detail":"Feed the people the Ferros couldn''t.","requiresWeakness":true,"exploits":true},{"id":"hold-vote","label":"Let your record speak","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('bike-launch', 1, 'product_launch', 'Launch Day: The Commuter Bike', '{"id":"bike-launch","version":1,"title":"Launch Day: The Commuter Bike","category":"product_launch","opponent":{"name":"Velocity Nine","role":"Rival e-bike brand (fictional)","style":"Big ad budget","color":"#3A86FF"},"objective":"Launch your commuter bike and hit pre-order goals.","meterLabel":"Pre-orders","startMeter":8,"target":32,"capital":7,"conditions":["Velocity Nine launches the same week.","Reviewers care about reliability."],"weakness":"Velocity Nine''s battery has a recall rumor they haven''t addressed.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"Pre-launch","situation":"Your landing page is ready. Their billboards are up.","signal":"Their ads only mention speed, never range.","intents":[{"id":"ad-blitz","label":"Launches an ad blitz","pressure":9,"weakTo":["research","negotiate"],"detail":"Ads on every commuter podcast.","weight":10},{"id":"discount-preorder","label":"Undercuts with pre-order discounts","pressure":9,"weakTo":["invest"],"detail":"$300 off for early buyers.","weight":10}],"choices":[{"id":"teardown","label":"Tear down their spec sheet","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Find what they aren''t saying.","reveals":true},{"id":"reviewer-loans","label":"Loan bikes to reviewers","tag":"negotiate","stat":"influence","cost":2,"power":9,"detail":"Let reliability speak."},{"id":"warranty","label":"Offer a 5-year warranty","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Make reliability a promise."},{"id":"hold-pre","label":"Stay on schedule","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Launch day","situation":"Orders are trickling in. A server hiccups.","signal":"Their CEO is doing interviews all day.","intents":[{"id":"media-tour","label":"Floods the media","pressure":10,"weakTo":["negotiate"],"detail":"Their CEO is on every show.","weight":10},{"id":"site-crash","label":"Your checkout strains","pressure":11,"weakTo":["execute","defend"],"detail":"Traffic spikes; checkout slows down.","weight":10}],"choices":[{"id":"scale-checkout","label":"Scale your checkout","tag":"execute","stat":"execution","cost":2,"power":9,"detail":"Keep the store fast."},{"id":"range-story","label":"Publish real-world range tests","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Show the commute, not the billboard.","exploits":true},{"id":"referral","label":"Launch a referral program","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Riders bring riders.","yield":1},{"id":"hold-launch","label":"Keep calm, fix bugs","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Week one","situation":"Reviews are coming in.","signal":"A forum thread asks about Velocity''s batteries.","intents":[{"id":"price-cut","label":"Cuts price again","pressure":12,"weakTo":["invest","research"],"detail":"Another $200 off.","weight":10},{"id":"influencers","label":"Pays influencers","pressure":11,"weakTo":["negotiate","defend"],"detail":"Sponsored rides across the city.","weight":10}],"choices":[{"id":"battery-safety","label":"Publish your battery certification","tag":"negotiate","stat":"influence","cost":1,"power":10,"detail":"Answer the question they won''t.","requiresWeakness":true,"exploits":true},{"id":"ship-early","label":"Ship the first batch early","tag":"execute","stat":"execution","cost":2,"power":11,"detail":"Bikes in hands beat ads."},{"id":"cohort-data","label":"Study who''s ordering","tag":"research","stat":"insight","cost":1,"power":6,"detail":"Find your real customer.","reveals":true},{"id":"hold-week","label":"Protect your margin","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('app-relaunch', 1, 'product_launch', 'The Planner App Relaunch', '{"id":"app-relaunch","version":1,"title":"The Planner App Relaunch","category":"product_launch","opponent":{"name":"Tessa Ruiz","role":"Product lead, Plandex (fictional)","style":"Copies fast","color":"#06D6A0"},"objective":"Relaunch your planner app and win back lapsed users.","meterLabel":"Active users","startMeter":10,"target":34,"capital":6,"conditions":["Plandex is free with ads.","Your old users left over sync bugs."],"weakness":"Plandex shows ads inside users'' calendars, and people hate it.","exploitBonus":4,"counterBonus":4,"rounds":[{"title":"Win-back email","situation":"You can email 40,000 lapsed users once.","signal":"Plandex just announced a ''privacy update''.","intents":[{"id":"feature-copy","label":"Copies your headline feature","pressure":9,"weakTo":["execute"],"detail":"Ships a clone in a week.","weight":10},{"id":"free-forever","label":"Pushes ''free forever''","pressure":8,"weakTo":["research","negotiate"],"detail":"Free beats paid in an ad.","weight":10}],"choices":[{"id":"churn-survey","label":"Survey why users left","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Ask, then listen.","reveals":true},{"id":"fix-sync","label":"Rebuild sync first","tag":"execute","stat":"execution","cost":2,"power":9,"detail":"Fix the reason they left."},{"id":"apology-email","label":"Send an honest apology email","tag":"negotiate","stat":"influence","cost":1,"power":7,"detail":"Own the bugs, show the fix."},{"id":"hold-email","label":"Wait for the fix","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Relaunch week","situation":"Your relaunch is live.","signal":"Tessa tweeted a screenshot of your pricing page.","intents":[{"id":"price-mock","label":"Mocks your pricing","pressure":10,"weakTo":["negotiate","invest"],"detail":"''Why pay for a calendar?''","weight":10},{"id":"bug-hunt","label":"Users find a bug","pressure":10,"weakTo":["execute","defend"],"detail":"A timezone bug in the new build.","weight":10}],"choices":[{"id":"hotfix","label":"Ship a same-day hotfix","tag":"execute","stat":"execution","cost":1,"power":8,"detail":"Fix it before lunch."},{"id":"no-ads-promise","label":"Promise a calendar without ads","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Your calendar, your time.","exploits":true},{"id":"family-plan","label":"Introduce a family plan","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"One price for the whole house.","yield":1},{"id":"hold-week","label":"Monitor and wait","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Month one","situation":"Retention data is in.","signal":"Plandex''s app-store rating is dropping.","intents":[{"id":"ad-free-tier","label":"Launches an ad-free tier","pressure":12,"weakTo":["invest","research"],"detail":"Matches your no-ads pitch.","weight":10},{"id":"partnerships","label":"Signs a phone-maker partnership","pressure":11,"weakTo":["negotiate"],"detail":"Preinstalled on new phones.","weight":10}],"choices":[{"id":"ad-comparison","label":"Show a side-by-side calendar","tag":"negotiate","stat":"influence","cost":1,"power":10,"detail":"Theirs with ads, yours without.","requiresWeakness":true,"exploits":true},{"id":"power-features","label":"Ship power-user features","tag":"execute","stat":"execution","cost":2,"power":10,"detail":"Give fans a reason to stay."},{"id":"retention-dive","label":"Dig into retention data","tag":"research","stat":"insight","cost":1,"power":6,"detail":"Find the habit that keeps users.","reveals":true},{"id":"hold-month","label":"Hold course","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('cookbook-launch', 1, 'product_launch', 'The Cookbook Launch', '{"id":"cookbook-launch","version":1,"title":"The Cookbook Launch","category":"product_launch","opponent":{"name":"Chef Anton Brel","role":"TV chef, Brel Kitchens (fictional)","style":"Famous, overbooked","color":"#FB8500"},"objective":"Get your family-recipe cookbook onto the regional bestseller list.","meterLabel":"Copies sold","startMeter":6,"target":28,"capital":6,"conditions":["Brel''s new book launches the same month.","Bookstores give endcaps to proven sellers."],"weakness":"Brel''s book is expensive and full of hard-to-find ingredients.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"Pre-orders","situation":"Your publisher gives you a small marketing budget.","signal":"Brel''s book has a glossy trailer.","intents":[{"id":"celebrity","label":"Leans on celebrity","pressure":8,"weakTo":["negotiate"],"detail":"Talk-show appearances.","weight":10},{"id":"endcap","label":"Books every endcap","pressure":9,"weakTo":["research","execute"],"detail":"Front-of-store placement everywhere.","weight":10}],"choices":[{"id":"reader-research","label":"Research home cooks","tag":"research","stat":"insight","cost":1,"power":3,"detail":"What do weeknight cooks actually want?","reveals":true},{"id":"store-visits","label":"Visit indie bookstores","tag":"negotiate","stat":"influence","cost":1,"power":7,"detail":"Handshakes with booksellers."},{"id":"recipe-cards","label":"Print free recipe cards","tag":"execute","stat":"execution","cost":1,"power":7,"detail":"Something to take home."},{"id":"hold-pre","label":"Save the budget","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Launch month","situation":"Your book is on shelves.","signal":"Readers post photos of failed Brel recipes.","intents":[{"id":"tv-special","label":"Airs a TV special","pressure":10,"weakTo":["negotiate","defend"],"detail":"An hour on prime time.","weight":10},{"id":"bulk-discount","label":"Bulk discounts to stores","pressure":9,"weakTo":["invest"],"detail":"Stores get Brel cheaper.","weight":10}],"choices":[{"id":"weeknight-demo","label":"Demo 20-minute dinners","tag":"execute","stat":"execution","cost":1,"power":8,"detail":"Real recipes, real kitchens.","exploits":true},{"id":"book-club","label":"Pitch book clubs","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Cook together, read together."},{"id":"library-copies","label":"Donate library copies","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Readers who borrow, buy.","yield":1},{"id":"hold-launch","label":"Let reviews build","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Bestseller week","situation":"The list is decided this week.","signal":"Brel is offering signed copies.","intents":[{"id":"signing-tour","label":"Runs a signing tour","pressure":11,"weakTo":["execute","negotiate"],"detail":"Ten cities in ten days.","weight":10},{"id":"price-drop","label":"Drops his price","pressure":11,"weakTo":["research"],"detail":"Brel goes half price.","weight":10}],"choices":[{"id":"pantry-promise","label":"Promote ''all from your pantry''","tag":"negotiate","stat":"influence","cost":1,"power":9,"detail":"No specialty stores required.","requiresWeakness":true,"exploits":true},{"id":"local-signing","label":"Do hometown signings","tag":"execute","stat":"execution","cost":1,"power":9,"detail":"Family, friends, and neighbors."},{"id":"sales-data","label":"Track store-by-store sales","tag":"research","stat":"insight","cost":1,"power":6,"detail":"Restock where it''s selling.","reveals":true},{"id":"hold-list","label":"Hold steady","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('warehouse-crunch', 1, 'operations', 'The Holiday Warehouse Crunch', '{"id":"warehouse-crunch","version":1,"title":"The Holiday Warehouse Crunch","category":"operations","opponent":{"name":"The Peak Season","role":"A brutal December (fictional scenario)","style":"Relentless","color":"#457B9D"},"objective":"Ship every holiday order on time with a small team.","meterLabel":"Orders on time","startMeter":10,"target":32,"capital":6,"conditions":["Orders are tripling.","Two packers are out sick."],"weakness":"Most orders are the same three products.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"The surge","situation":"Orders triple overnight.","signal":"The carrier pickup window just moved earlier.","intents":[{"id":"carrier-cutoff","label":"Earlier carrier cutoff","pressure":9,"weakTo":["execute"],"detail":"Pickups move to 2 p.m.","weight":10},{"id":"stockout","label":"Stock runs low","pressure":8,"weakTo":["research","invest"],"detail":"Top seller nearly gone.","weight":10}],"choices":[{"id":"order-analysis","label":"Analyze the order mix","tag":"research","stat":"insight","cost":1,"power":3,"detail":"What are people actually buying?","reveals":true},{"id":"second-shift","label":"Add a second shift","tag":"execute","stat":"execution","cost":2,"power":9,"detail":"More hours on the floor."},{"id":"reorder","label":"Place a rush reorder","tag":"invest","stat":"insight","cost":2,"power":8,"detail":"Get stock in before it''s gone."},{"id":"hold-surge","label":"Work the queue in order","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Bottleneck","situation":"Packing is the bottleneck.","signal":"Customer emails asking ''where is my order?'' are rising.","intents":[{"id":"complaints","label":"Customer complaints spike","pressure":10,"weakTo":["negotiate"],"detail":"Angry emails and reviews.","weight":10},{"id":"packing-jam","label":"Packing station jams","pressure":10,"weakTo":["execute","defend"],"detail":"Two stations break down.","weight":10}],"choices":[{"id":"pre-pack","label":"Pre-pack the top three products","tag":"execute","stat":"execution","cost":1,"power":9,"detail":"Batch the common orders.","exploits":true},{"id":"proactive-email","label":"Email every customer an update","tag":"negotiate","stat":"influence","cost":1,"power":7,"detail":"Honest delivery dates."},{"id":"rent-equipment","label":"Rent a second packing line","tag":"invest","stat":"insight","cost":3,"power":11,"detail":"Throughput for money."},{"id":"hold-bottleneck","label":"Keep going steady","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Final week","situation":"Last shipping day before the holidays.","signal":"The forecast shows snow on the carrier''s route.","intents":[{"id":"snowstorm","label":"Snowstorm delays","pressure":12,"weakTo":["research","invest"],"detail":"Carrier delays across the region.","weight":10},{"id":"returns-wave","label":"Early returns pile up","pressure":11,"weakTo":["execute"],"detail":"Returns clog the dock.","weight":10}],"choices":[{"id":"batch-ship","label":"Ship batched orders first","tag":"execute","stat":"execution","cost":1,"power":10,"detail":"Clear the biggest piles first.","requiresWeakness":true,"exploits":true},{"id":"local-courier","label":"Book a local courier","tag":"invest","stat":"insight","cost":2,"power":10,"detail":"A backup carrier for local orders."},{"id":"gift-notes","label":"Send gift-note emails for late orders","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"A printable note while they wait."},{"id":"hold-final","label":"Ship what you can","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('kitchen-turnaround', 1, 'operations', 'The Kitchen Turnaround', '{"id":"kitchen-turnaround","version":1,"title":"The Kitchen Turnaround","category":"operations","opponent":{"name":"Inspector Ilse Varga","role":"City health inspector (fictional)","style":"Thorough, fair","color":"#118AB2"},"objective":"Turn around a struggling restaurant kitchen before re-inspection.","meterLabel":"Kitchen score","startMeter":8,"target":30,"capital":6,"conditions":["Re-inspection is in three weeks.","The staff is demoralized."],"weakness":"Varga focuses on records and repeat issues, not one-off mistakes.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"Week one","situation":"You inherit a messy kitchen and a tired crew.","signal":"Last report circled ''temperature logs'' twice.","intents":[{"id":"morale-dip","label":"Crew morale dips","pressure":8,"weakTo":["negotiate"],"detail":"Two cooks talk about quitting.","weight":10},{"id":"equipment-fail","label":"Walk-in cooler struggles","pressure":9,"weakTo":["research","execute"],"detail":"The cooler won''t hold temperature.","weight":10}],"choices":[{"id":"past-reports","label":"Read every past report","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Find the patterns.","reveals":true},{"id":"crew-meeting","label":"Hold a crew meeting","tag":"negotiate","stat":"influence","cost":1,"power":7,"detail":"Listen first, then plan together."},{"id":"repair-cooler","label":"Replace the cooler outright","tag":"invest","stat":"insight","cost":3,"power":10,"detail":"Fix the expensive problem with money."},{"id":"hold-week1","label":"Deep clean with what you have","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Week two","situation":"Systems are forming.","signal":"A cook forgets the logbook during the rush.","intents":[{"id":"rush-chaos","label":"Dinner rush chaos","pressure":10,"weakTo":["execute","defend"],"detail":"Standards slip during the rush.","weight":10},{"id":"supplier-late","label":"Supplier delivers late and warm","pressure":9,"weakTo":["negotiate","research"],"detail":"A delivery arrives at unsafe temperature.","weight":10}],"choices":[{"id":"log-system","label":"Install a simple logging routine","tag":"execute","stat":"execution","cost":1,"power":9,"detail":"Checklists at every station.","exploits":true},{"id":"supplier-call","label":"Renegotiate delivery terms","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Cold-chain guarantees in writing."},{"id":"new-thermometers","label":"Buy new prep equipment","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Shiny tools for every station."},{"id":"hold-week2","label":"Slow the menu down","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Re-inspection","situation":"Varga arrives at 10 a.m.","signal":"She asks to see records before she looks at the line.","intents":[{"id":"records-review","label":"Reviews three weeks of logs","pressure":12,"weakTo":["research","execute"],"detail":"Every gap will show.","weight":10},{"id":"surprise-check","label":"Checks the walk-in first","pressure":11,"weakTo":["negotiate"],"detail":"Temperatures, labels, dates.","weight":10}],"choices":[{"id":"show-records","label":"Present complete logs","tag":"execute","stat":"execution","cost":1,"power":10,"detail":"Three weeks, no gaps.","requiresWeakness":true,"exploits":true},{"id":"walkthrough","label":"Walk her through the changes","tag":"negotiate","stat":"influence","cost":1,"power":9,"detail":"Explain every fix."},{"id":"label-everything","label":"Buy a labeling system","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"No mystery containers."},{"id":"hold-inspect","label":"Let the kitchen speak","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('school-bid', 1, 'competitive_bid', 'The School Furniture Bid', '{"id":"school-bid","version":1,"title":"The School Furniture Bid","category":"competitive_bid","opponent":{"name":"Brandt & Sons","role":"Furniture contractor (fictional)","style":"Lowballs, then bills extras","color":"#6D597A"},"objective":"Win the district contract to furnish three new classrooms.","meterLabel":"Bid strength","startMeter":8,"target":32,"capital":6,"conditions":["The district weighs price and durability.","Brandt has won the last two bids."],"weakness":"Brandt''s last two jobs ran 30% over budget in change orders.","exploitBonus":4,"counterBonus":4,"rounds":[{"title":"Request for proposals","situation":"The district publishes its requirements.","signal":"The board minutes mention ''budget overruns'' twice.","intents":[{"id":"lowball","label":"Lowballs the price","pressure":9,"weakTo":["research"],"detail":"Bids 20% under everyone.","weight":10},{"id":"relationship","label":"Leans on relationships","pressure":8,"weakTo":["negotiate"],"detail":"Lunches with the facilities manager.","weight":10}],"choices":[{"id":"public-records","label":"Read past contract records","tag":"research","stat":"insight","cost":1,"power":3,"detail":"Public records show what jobs really cost.","reveals":true},{"id":"sample-desk","label":"Build a sample desk","tag":"execute","stat":"execution","cost":2,"power":9,"detail":"Let them sit in it."},{"id":"meet-facilities","label":"Meet the facilities team","tag":"negotiate","stat":"influence","cost":1,"power":7,"detail":"Learn what breaks and why."},{"id":"hold-rfp","label":"Submit a clean, standard bid","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Shortlist","situation":"You and Brandt are the finalists.","signal":"Brandt''s rep keeps calling the board chair.","intents":[{"id":"price-war","label":"Cuts price again","pressure":10,"weakTo":["invest","research"],"detail":"Another 5% off.","weight":10},{"id":"lobbying","label":"Lobbies the board","pressure":10,"weakTo":["negotiate","defend"],"detail":"Private calls to board members.","weight":10}],"choices":[{"id":"fixed-price","label":"Guarantee a fixed price","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"No change orders, ever.","exploits":true},{"id":"durability-test","label":"Publish durability tests","tag":"execute","stat":"execution","cost":1,"power":8,"detail":"10,000 sit tests, on video."},{"id":"teacher-feedback","label":"Invite teachers to try samples","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"The people who use it every day."},{"id":"hold-short","label":"Stay out of politics","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Board vote","situation":"The board votes tonight.","signal":"A board member asks about ''total cost'' in the agenda.","intents":[{"id":"final-cut","label":"Promises a final discount","pressure":12,"weakTo":["research","invest"],"detail":"Cheapest on paper.","weight":10},{"id":"doubt-campaign","label":"Questions your capacity","pressure":11,"weakTo":["execute","defend"],"detail":"''Can a small shop deliver on time?''","weight":10}],"choices":[{"id":"total-cost","label":"Present total cost with overruns","tag":"negotiate","stat":"influence","cost":1,"power":10,"detail":"Show what Brandt''s jobs really cost.","requiresWeakness":true,"exploits":true},{"id":"delivery-plan","label":"Show a delivery schedule","tag":"execute","stat":"execution","cost":1,"power":9,"detail":"Week-by-week, with a buffer."},{"id":"warranty-bond","label":"Post a performance bond","tag":"invest","stat":"insight","cost":2,"power":10,"detail":"Money where your mouth is."},{"id":"hold-vote","label":"Rest on your bid","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
insert into earned.battle_definitions (id, version, category, title, content) values ('city-catering', 1, 'competitive_bid', 'The City Hall Catering Contract', '{"id":"city-catering","version":1,"title":"The City Hall Catering Contract","category":"competitive_bid","opponent":{"name":"Gilded Fork Events","role":"Upscale caterer (fictional)","style":"Polished, pricey","color":"#FFB703"},"objective":"Win City Hall''s yearly catering contract.","meterLabel":"Contract odds","startMeter":8,"target":30,"capital":6,"conditions":["City Hall wants local and affordable.","Gilded Fork catered the mayor''s gala."],"weakness":"Gilded Fork sources almost nothing locally.","exploitBonus":3,"counterBonus":4,"rounds":[{"title":"Tasting invite","situation":"Both caterers are invited to a tasting.","signal":"The procurement memo highlights ''local sourcing''.","intents":[{"id":"gala-menu","label":"Brings a gala menu","pressure":8,"weakTo":["research"],"detail":"Lobster and champagne.","weight":10},{"id":"connections","label":"Name-drops the mayor","pressure":9,"weakTo":["negotiate"],"detail":"''The mayor loved our gala.''","weight":10}],"choices":[{"id":"procurement-rules","label":"Read the procurement rules","tag":"research","stat":"insight","cost":1,"power":3,"detail":"What does City Hall actually score?","reveals":true},{"id":"local-menu","label":"Design a local-farm menu","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Seasonal, local, affordable."},{"id":"staff-pitch","label":"Pitch your service team","tag":"negotiate","stat":"influence","cost":1,"power":7,"detail":"Friendly, fast, reliable."},{"id":"hold-tasting","label":"Bring your standard menu","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"The tasting","situation":"The committee tastes both menus.","signal":"One committee member has a dairy allergy.","intents":[{"id":"presentation","label":"Wows with presentation","pressure":10,"weakTo":["execute"],"detail":"Ice sculptures and towers.","weight":10},{"id":"price-hint","label":"Hints at a discount","pressure":9,"weakTo":["negotiate","defend"],"detail":"''We can be flexible.''","weight":10}],"choices":[{"id":"allergy-plan","label":"Show an allergy-safe plan","tag":"execute","stat":"execution","cost":1,"power":9,"detail":"Labels and separate prep for every dish."},{"id":"farm-story","label":"Tell your farms'' story","tag":"negotiate","stat":"influence","cost":1,"power":8,"detail":"Names and towns of every supplier.","exploits":true},{"id":"tasting-boxes","label":"Send tasting boxes to staff","tag":"invest","stat":"insight","cost":2,"power":9,"detail":"Let the whole office try.","yield":1},{"id":"hold-taste","label":"Let the food speak","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]},{"title":"Decision","situation":"The committee decides Friday.","signal":"Gilded Fork requested a private meeting.","intents":[{"id":"private-meeting","label":"Lobbies privately","pressure":11,"weakTo":["negotiate","research"],"detail":"A closed-door pitch.","weight":10},{"id":"bundle-offer","label":"Offers a free gala","pressure":12,"weakTo":["execute"],"detail":"A free holiday party with the contract.","weight":10}],"choices":[{"id":"local-scorecard","label":"Submit a local-sourcing scorecard","tag":"negotiate","stat":"influence","cost":1,"power":10,"detail":"Show the percentages side by side.","requiresWeakness":true,"exploits":true},{"id":"pilot-month","label":"Offer a one-month pilot","tag":"execute","stat":"execution","cost":1,"power":9,"detail":"Earn it month by month."},{"id":"price-lock","label":"Lock prices for the year","tag":"invest","stat":"insight","cost":2,"power":10,"detail":"Predictable costs for the city."},{"id":"hold-decision","label":"Wait for the vote","tag":"defend","stat":"execution","cost":0,"power":2,"detail":"No spend.","defense":5}]}]}'::jsonb) on conflict (id) do update set version = excluded.version, category = excluded.category, title = excluded.title, content = excluded.content;
